def evaluasi(flag, p):
    if not flag["aktif"]:
        return flag["bawaan"]
    if p["uid"] in flag["daftar"]:
        return True
    for atr, nilai in flag["aturan"]:
        if p.get(atr) == nilai:
            return True
    return bucket(flag["salt"],
        p["uid"]) < flag["persen"]

def varian(salt, uid, bobot):
    b, batas = bucket(salt, uid), 0
    for nama, persen in bobot.items():
        batas += persen
        if b < batas:
            return nama

